package dev.rgcb.scholar.mechanical;
import static org.junit.jupiter.api.Assertions.*;
import dev.rgcb.scholar.diagram.*; import dev.rgcb.scholar.document.*; import dev.rgcb.scholar.editor.*; import dev.rgcb.scholar.mechanical.editor.MechanicalDiagramEditor; import java.util.*; import org.junit.jupiter.api.Test;
class MechanicalAnnotationTest {
 @Test void annotationsAreSemanticEditableAndDeletable(){var block=new DiagramBlock(new DiagramDefinition("A",new DiagramCanvas(120,80),List.of(new MechanicalPrimitive(new DiagramElementId("p"),new DiagramBounds(2,2,20,8),MechanicalPrimitiveKind.LINE)),List.of()));var ed=new MechanicalDiagramEditor();var r=ed.addAnnotation(block,new DiagramElementTarget(0,new DiagramElementId("p")),MechanicalAnnotationKind.LEADER);assertTrue(r.changed());var a=(MechanicalAnnotation)r.diagram().definition().elements().get(1);assertEquals("CALLOUT",a.text());var t=new DiagramElementTarget(1,a.id());var renamed=ed.setAnnotationText(r.diagram(),t,"M6 HOLE");assertEquals("M6 HOLE",((MechanicalAnnotation)renamed.diagram().definition().elements().get(1)).text());assertTrue(ed.deleteAnnotation(renamed.diagram(),t).changed());}
 @Test void allKindsCanBeAuthored(){var block=new DiagramBlock(new DiagramDefinition("A",new DiagramCanvas(120,80),List.of(new MechanicalPrimitive(new DiagramElementId("p"),new DiagramBounds(2,2,20,8),MechanicalPrimitiveKind.LINE)),List.of()));var ed=new MechanicalDiagramEditor();for(var k:MechanicalAnnotationKind.values()){var r=ed.addAnnotation(block,new DiagramElementTarget(0,new DiagramElementId("p")),k);assertEquals(k,((MechanicalAnnotation)r.diagram().definition().elements().get(1)).kind());}}
}
